CREATE TABLE rol (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(255) NOT NULL UNIQUE CHECK(nombre IN ('CIUDADANO','OPERADOR','RESPONSABLE_ATENCION')));
CREATE TABLE usuario (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(255) NOT NULL, correo_electronico VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, enabled BOOLEAN NOT NULL, created_at TIMESTAMP NOT NULL, rol_id BIGINT NOT NULL REFERENCES rol(id));
CREATE TABLE categoria (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(255) NOT NULL UNIQUE, descripcion VARCHAR(255), activa BOOLEAN NOT NULL);
CREATE TABLE zona (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nombre VARCHAR(255) NOT NULL, referencia VARCHAR(255), activa BOOLEAN NOT NULL);
CREATE TABLE reporte (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, categoria_id BIGINT NOT NULL REFERENCES categoria(id), zona_id BIGINT NOT NULL REFERENCES zona(id), propietario_id BIGINT NOT NULL REFERENCES usuario(id), titulo VARCHAR(255) NOT NULL, descripcion VARCHAR(4000) NOT NULL, estado VARCHAR(255) NOT NULL CHECK(estado IN ('REGISTRADO','EN_REVISION','EN_ATENCION','RESUELTO','CERRADO')), prioridad VARCHAR(255) NOT NULL CHECK(prioridad IN ('BAJA','MEDIA','ALTA')), fecha_creacion TIMESTAMP NOT NULL, fecha_actualizacion TIMESTAMP NOT NULL, version BIGINT);
CREATE TABLE evidencia (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reporte_id BIGINT NOT NULL REFERENCES reporte(id), tipo VARCHAR(255) NOT NULL, referencia_ficticia VARCHAR(255) NOT NULL, descripcion VARCHAR(255), fecha_registro TIMESTAMP NOT NULL);
CREATE TABLE seguimiento (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reporte_id BIGINT NOT NULL REFERENCES reporte(id), estado_anterior VARCHAR(255) NOT NULL, estado_nuevo VARCHAR(255) NOT NULL, comentario VARCHAR(2000) NOT NULL, actor_rol VARCHAR(255) NOT NULL, fecha TIMESTAMP NOT NULL);
CREATE TABLE evento_contexto (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, reporte_id BIGINT NOT NULL REFERENCES reporte(id), fuente VARCHAR(255) NOT NULL, instante TIMESTAMP NOT NULL, variable VARCHAR(255) NOT NULL, unidad VARCHAR(255) NOT NULL, valor NUMERIC(19,6) NOT NULL, interpretacion VARCHAR(255));
CREATE INDEX idx_reporte_propietario ON reporte(propietario_id);
CREATE INDEX idx_reporte_filters ON reporte(estado,prioridad,categoria_id,zona_id);
CREATE INDEX idx_evidencia_reporte ON evidencia(reporte_id);
CREATE INDEX idx_seguimiento_reporte ON seguimiento(reporte_id,fecha,id);
CREATE INDEX idx_evento_reporte ON evento_contexto(reporte_id,instante);
INSERT INTO rol(nombre) VALUES ('CIUDADANO'),('OPERADOR'),('RESPONSABLE_ATENCION');
